#!BASH
set -e
python - <<'PY'
import requests, json, urllib.parse, re
H={'User-Agent':'Mozilla/5.0 research client'}

def show(text, n=12000):
    print(text[:n])

print('=== Europe PMC: titles/abstracts mentioning Allosteric Database ===')
for q in ['"allosteric database"','TITLE:"allosteric database"','"AlloDB"','allostery database curated sites']:
    u='https://www.ebi.ac.uk/europepmc/webservices/rest/search'
    r=requests.get(u,params={'query':q,'format':'json','pageSize':100,'resultType':'core'},headers=H,timeout=60)
    print('\nQUERY',q,'status',r.status_code)
    if not r.ok: continue
    for x in r.json().get('resultList',{}).get('result',[]):
        title=x.get('title','')
        if any(k in title.lower() for k in ['alloster','database','allodb']):
            print('ID',x.get('id'),'TITLE',title,'AUTH',x.get('authorString'),'YEAR',x.get('pubYear'),'DOI',x.get('doi'),'PMID',x.get('pmid'))
            print('ABSTRACT',re.sub('<[^>]+>',' ',x.get('abstractText',''))[:700])

print('\n=== Crossref: allosteric database ===')
r=requests.get('https://api.crossref.org/works',params={'query.title':'allosteric database','rows':100,'select':'DOI,title,author,published,URL,type'},headers=H,timeout=60)
print('status',r.status_code)
if r.ok:
    for x in r.json()['message']['items']:
        title='; '.join(x.get('title',[]))
        if 'alloster' in title.lower() or 'allodb' in title.lower():
            print('DOI',x.get('DOI'),'TITLE',title,'URL',x.get('URL'))

print('\n=== OpenAlex: allosteric database ===')
r=requests.get('https://api.openalex.org/works',params={'search':'allosteric database','per-page':100,'mailto':'<EMAIL>'},headers=H,timeout=60)
print('status',r.status_code)
if r.ok:
    for x in r.json().get('results',[]):
        title=x.get('display_name','')
        if 'alloster' in title.lower() or 'allodb' in title.lower():
            print('ID',x.get('id'),'TITLE',title,'DOI',x.get('doi'))

print('\n=== Internet Archive CDX: allostericdb.org ===')
for target in ['allostericdb.org','www.allostericdb.org','allostericdb.org/*','www.allostericdb.org/*']:
    u='https://web.archive.org/cdx/search/cdx'
    try:
        r=requests.get(u,params={'url':target,'output':'json','filter':'statuscode:200','fl':'timestamp,original,statuscode,mimetype','collapse':'urlkey','limit':100},headers=H,timeout=90)
        print('\nTARGET',target,'status',r.status_code,'bytes',len(r.content)); show(r.text,5000)
    except Exception as e: print('ERROR',e)

print('\n=== Common Crawl index: allostericdb.org ===')
for idx in ['CC-MAIN-2026-30','CC-MAIN-2025-47','CC-MAIN-2024-51','CC-MAIN-2023-50']:
    u=f'https://index.commoncrawl.org/{idx}-index'
    try:
        r=requests.get(u,params={'url':'allostericdb.org/*','output':'json','filter':'status:200'},headers=H,timeout=90)
        print('\nINDEX',idx,'status',r.status_code,'bytes',len(r.content)); show(r.text,5000)
    except Exception as e: print('ERROR',e)
